"""Generated by solo-to-scale; edit `templates/.claude/statusline.py` in the plugin.

Status-line shim. Plugins can't register a status line, so this file finds the solo-to-scale plugin
(its session-start hook records where it is) and runs the plugin's status line. Fails safe.
"""
import json
import runpy
import sys
from pathlib import Path

try:
    root = json.loads((Path(__file__).parent / "state" / "plugin.json").read_text(encoding="utf-8"))["root"]
    sys.argv = [sys.argv[0], "--agent", "claude"]
    runpy.run_path(str(Path(root) / "scripts" / "hooks" / "statusline.py"), run_name="__main__")
except SystemExit:
    pass
except Exception:  # noqa: BLE001
    print("Claude")
